import{_ as r,o as e,c as a,ag as l}from"./chunks/framework.BcZEdlUI.js";const u=JSON.parse('{"title":"ADR-002: 全量本地处理 vs 云端渲染","description":"","frontmatter":{},"headers":[],"relativePath":"adr/002-local-processing-vs-cloud-rendering.md","filePath":"adr/002-local-processing-vs-cloud-rendering.md","lastUpdated":1781581339000}'),i={name:"adr/002-local-processing-vs-cloud-rendering.md"};function n(o,t,s,d,g,h){return e(),a("div",null,[...t[0]||(t[0]=[l('<h1 id="adr-002-全量本地处理-vs-云端渲染" tabindex="-1">ADR-002: 全量本地处理 vs 云端渲染 <a class="header-anchor" href="#adr-002-全量本地处理-vs-云端渲染" aria-label="Permalink to &quot;ADR-002: 全量本地处理 vs 云端渲染&quot;">​</a></h1><ul><li><strong>状态</strong>: ✅ Accepted</li><li><strong>日期</strong>: 2026-06-04</li><li><strong>作者</strong>: 架构团队</li><li><strong>关联版本</strong>: v1.0.0 ~ v2.0.0</li></ul><h2 id="背景" tabindex="-1">背景 <a class="header-anchor" href="#背景" aria-label="Permalink to &quot;背景&quot;">​</a></h2><p>AI 影视解说工具的核心计算任务（视频分析、LLM 推理、TTS 合成、FFmpeg 合成）可以选择：</p><ol><li><strong>全量本地处理</strong>：在用户本机完成所有计算</li><li><strong>云端渲染</strong>：上传源文件到云端处理后下载</li><li><strong>混合模式</strong>：小计算本地 + 大计算云端</li></ol><h2 id="决策" tabindex="-1">决策 <a class="header-anchor" href="#决策" aria-label="Permalink to &quot;决策&quot;">​</a></h2><p>采用 <strong>全量本地处理</strong> + LLM/TTS API 可选的混合策略。</p><h2 id="关键理由" tabindex="-1">关键理由 <a class="header-anchor" href="#关键理由" aria-label="Permalink to &quot;关键理由&quot;">​</a></h2><h3 id="业务层面" tabindex="-1">业务层面 <a class="header-anchor" href="#业务层面" aria-label="Permalink to &quot;业务层面&quot;">​</a></h3><ul><li><strong>素材隐私</strong>：影视解说涉及版权敏感素材，创作者不愿上传第三方</li><li><strong>数据安全</strong>：v1.0 调研时 78% 创作者表达了对云端处理的担忧</li><li><strong>离线可用</strong>：本地处理不依赖网络，可用性更高</li></ul><h3 id="技术层面" tabindex="-1">技术层面 <a class="header-anchor" href="#技术层面" aria-label="Permalink to &quot;技术层面&quot;">​</a></h3><ul><li><strong>GPU 利用率</strong>：现代创作者工作站（Mac/PC）已具备 GPU，本地推理更可控</li><li><strong>FFmpeg 本地化</strong>：FFmpeg + CUDA/NVENC 加速已成熟</li><li><strong>F5-TTS 零样本</strong>：本地音色克隆无延迟，零样本合成</li><li><strong>OpenCV 帧处理</strong>：CPU/NVENC 解码成熟</li></ul><h3 id="成本层面" tabindex="-1">成本层面 <a class="header-anchor" href="#成本层面" aria-label="Permalink to &quot;成本层面&quot;">​</a></h3><ul><li><strong>无服务器成本</strong>：不投入云端算力，毛利率 = 100%</li><li><strong>无 API 流量费</strong>：除 LLM/Vision API Key 外无费用</li><li><strong>无限使用</strong>：用户不被调用次数/并发限制</li></ul><h2 id="llm-视觉-api-处理" tabindex="-1">LLM/视觉 API 处理 <a class="header-anchor" href="#llm-视觉-api-处理" aria-label="Permalink to &quot;LLM/视觉 API 处理&quot;">​</a></h2><table tabindex="0"><thead><tr><th>组件</th><th style="text-align:center;">本地/云端</th><th>说明</th></tr></thead><tbody><tr><td>视频帧分析</td><td style="text-align:center;">云端 API</td><td>Qwen3.7 / Gemini Vision / Claude Vision</td></tr><tr><td>解说稿生成</td><td style="text-align:center;">云端 API</td><td>DeepSeek / Qwen / Kimi / GLM-5 等</td></tr><tr><td>配音合成</td><td style="text-align:center;"><strong>双模式</strong></td><td>Edge-TTS（云端免费）/ F5-TTS（本地零样本）</td></tr><tr><td>帧提取</td><td style="text-align:center;"><strong>本地</strong></td><td>FFmpeg + OpenCV</td></tr><tr><td>视频合成</td><td style="text-align:center;"><strong>本地</strong></td><td>FFmpeg + 可选 CUDA</td></tr><tr><td>情感分析</td><td style="text-align:center;"><strong>本地</strong></td><td>OpenCV + librosa</td></tr></tbody></table><h2 id="后果" tabindex="-1">后果 <a class="header-anchor" href="#后果" aria-label="Permalink to &quot;后果&quot;">​</a></h2><ul><li>✅ 用户数据完全自主，零隐私担忧</li><li>✅ 商业模式简单（无服务器运营成本）</li><li>⚠️ 用户机器性能影响体验（需 README 提示最低配置）</li><li>⚠️ LLM/Vision API 仍依赖云端（不可避免）</li></ul><h2 id="替代方案探索" tabindex="-1">替代方案探索 <a class="header-anchor" href="#替代方案探索" aria-label="Permalink to &quot;替代方案探索&quot;">​</a></h2><ul><li><strong>全云端渲染</strong>: 拒绝（隐私 + 成本）</li><li><strong>P2P 算力网络</strong>: 拒绝（运维复杂度）</li><li><strong>Serverless GPU (如 RunPod)</strong>: 评估中（未来可作 P3 长期目标）</li></ul><h2 id="评审" tabindex="-1">评审 <a class="header-anchor" href="#评审" aria-label="Permalink to &quot;评审&quot;">​</a></h2><ul><li>决策已写入 README.md 产品定位</li><li>与当前 README.md 产品定位中的&quot;本地优先&quot;原则一致</li></ul>',22)])])}const P=r(i,[["render",n]]);export{u as __pageData,P as default};
